import * as React from 'react';
import * as ScrollTimelinePrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface ScrollTimelineProps extends React.ComponentPropsWithoutRef<typeof ScrollTimelinePrimitive.ScrollTimeline> {
  className?: string;
}

export const ScrollTimeline = React.forwardRef<HTMLDivElement, ScrollTimelineProps>(
  ({ className, children, ...props }, ref) => (
    <ScrollTimelinePrimitive.ScrollTimeline
      ref={ref}
      className={clsx(
        'relative max-w-4xl mx-auto py-16 px-4',
        className
      )}
      {...props}
    >
      {children}
    </ScrollTimelinePrimitive.ScrollTimeline>
  )
);
ScrollTimeline.displayName = 'ScrollTimeline';

