import { Component, JSX, splitProps } from 'solid-js';
import * as ScrollTimelinePrimitive from '@exhuma/core';

export interface ScrollTimelineProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const ScrollTimeline: Component<ScrollTimelineProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <ScrollTimelinePrimitive.ScrollTimeline
      class={`relative max-w-4xl mx-auto py-16 px-4 ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </ScrollTimelinePrimitive.ScrollTimeline>
  );
};

