import { ScrollTimeline } from '@exhuma/core';

class ExhumaScrollTimelineElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-scroll-timeline');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-scroll-timeline')) {
  customElements.define('exhuma-scroll-timeline', ExhumaScrollTimelineElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as ScrollTimelinePrimitive from '@exhuma/core';

export interface ScrollTimelineProps extends ViewProps {
  children?: React.ReactNode;
}

export function ScrollTimeline({ style, children, ...props }: ScrollTimelineProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

